class Solution {

    /**
     * @param String[] $words
     * @return Integer[]
     */
    function groupStrings($words) {
        // Represent each word as a bitmask of letters
        $masks = [];
        foreach($words as $w) {
            $mask = 0;
            for ($i = 0; $i < strlen($w); $i++) {
                $mask |= 1 << (ord($w[$i]) - ord('a'));
            }
            $masks[] = $mask;
        }

        $n = count($masks);

        // Disjoint set union (DSU) to group connected words
        $parent = range(0, $n - 1);
        $size = array_fill(0, $n, 1);

        function find(&$parent, $x) {
            while ($parent[$x] != $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        }
        function union(&$parent, &$size, $a, $b) {
            $pa = find($parent, $a);
            $pb = find($parent, $b);
            if ($pa != $pb) {
                if ($size[$pa] < $size[$pb]) {
                    list($pa, $pb) = [$pb, $pa];
                }
                $parent[$pb] = $pa;
                $size[$pa] += $size[$pb];
            }
        }

        // Map mask to index(es) for quick lookup of exact matches
        // We only store one index per mask because duplicates aren't mentioned but if duplicates 
        // exist, any is fine for union since they share the same mask.
        $maskToIndex = [];
        for ($i = 0; $i < $n; $i++) {
            $maskToIndex[$masks[$i]] = $i;
        }

        /*
        For each mask, we find masks connected to it by the operations:
        - Add exactly one letter: mask2 = mask | (1 << c), where c is not set in mask
        - Delete exactly one letter: mask2 = mask & ~(1 << c), where c is set in mask
        - Replace one letter: replace one letter c1 in mask with c2 not in mask,
          which can be thought of as: mask2 = (mask ^ (1 << c1)) | (1 << c2),
          but that is same as: mask2 = mask - c1 + c2 (with c1 != c2)
          Also replacing with the same letter means mask2 == mask, so it counts as connected to itself (we can ignore that),
          no need to union as it's itself.
        */

        for ($i = 0; $i < $n; $i++) {
            $mask = $masks[$i];

            // Add one letter (only bits not set in mask)
            for ($c = 0; $c < 26; $c++) {
                $bit = 1 << $c;
                if (($mask & $bit) == 0) {
                    $newMask = $mask | $bit;
                    if (isset($maskToIndex[$newMask])) {
                        union($parent, $size, $i, $maskToIndex[$newMask]);
                    }
                }
            }

            // Delete one letter (bits set in mask)
            for ($c = 0; $c < 26; $c++) {
                $bit = 1 << $c;
                if (($mask & $bit) != 0) {
                    $newMask = $mask & (~$bit);
                    if (isset($maskToIndex[$newMask])) {
                        union($parent, $size, $i, $maskToIndex[$newMask]);
                    }
                }
            }

            // Replace one letter
            // For each c1 in mask, for each c2 not in mask, replace c1 by c2:
            // newMask = mask - c1 + c2
            for ($c1 = 0; $c1 < 26; $c1++) {
                $bit1 = 1 << $c1;
                if (($mask & $bit1) == 0) continue; // c1 not in mask, skip

                for ($c2 = 0; $c2 < 26; $c2++) {
                    $bit2 = 1 << $c2;
                    if (($mask & $bit2) != 0) continue; // c2 already in mask, skip

                    $newMask = ($mask ^ $bit1) | $bit2;
                    if (isset($maskToIndex[$newMask])) {
                        union($parent, $size, $i, $maskToIndex[$newMask]);
                    }
                }
            }
        }

        // Now count how many disjoint groups and max group size
        $groups = 0;
        $maxGroupSize = 0;
        $countGroup = [];
        for ($i = 0; $i < $n; $i++) {
            $p = find($parent, $i);
            if (!isset($countGroup[$p])) {
                $countGroup[$p] = 0;
            }
            $countGroup[$p]++;
        }

        foreach ($countGroup as $c) {
            $groups++;
            if ($c > $maxGroupSize) {
                $maxGroupSize = $c;
            }
        }

        return [$groups, $maxGroupSize];
    }
}

